1	package netdiag
2	
3	import (
4		"context"
5		"fmt"
6		"log"
7		"net"
8		"net/netip"
9		"time"
10	
11		tea "charm.land/bubbletea/v2"
12	
13		"github.com/anthnel/devdesk/internal/docker"
14		"github.com/anthnel/devdesk/internal/engine"
15		"github.com/anthnel/devdesk/internal/netcheck"
16		"github.com/anthnel/devdesk/internal/nettrace"
17	)
18	
19	// pathChanCap holds a whole trace: every hop (at most MaxHopsLimit), the
20	// resolved message and the done message. The producer therefore never waits
21	// for a reader. Contract: resolved now carries source and ctr but is still one
22	// message, so 1 resolved + MaxHopsLimit (30) hops + 1 done = 32 = pathChanCap,
23	// and sendDone never evicts resolved with the real engine.
24	const pathChanCap = nettrace.MaxHopsLimit + 2
25	
26	// pathEngine is the seam between the path tab and the network: tests replace
27	// it with a fake.
28	type pathEngine struct {
29		supported func() error
30		resolve   func(ctx context.Context, host string) ([]netip.Addr, error)
31		route     func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error)
32		trace     func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error)
33	
34		engineName func() string                                                            // engine.Current().Name
35		engineOS   func(ctx context.Context) (string, error)                                // docker.EngineOperatingSystem
36		running    func(ctx context.Context) ([]docker.Container, error)                    // running containers only
37		inspect    func(ctx context.Context, id string) (docker.ContainerNetworking, error) // read-only
38	}
39	
40	// systemPathEngine returns the engine backed by the real resolver and sockets.
41	func systemPathEngine() pathEngine {
42		env := netcheck.SystemEnv(netcheck.DefaultSettings())
43		return pathEngine{
44			supported: nettrace.Supported,
45			resolve: func(ctx context.Context, host string) ([]netip.Addr, error) {
46				return net.DefaultResolver.LookupNetIP(ctx, "ip4", host)
47			},
48			route: func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error) {
49				return env.Route(ctx, net.IP(a.AsSlice()))
50			},
51			trace:      nettrace.TraceEach,
52			engineName: func() string { return engine.Current().Name },
53			engineOS:   docker.EngineOperatingSystem,
54			running: func(ctx context.Context) ([]docker.Container, error) {
55				return docker.ListContainersContext(ctx, false)
56			},
57			inspect: docker.InspectContainerNetworking,
58		}
59	}
60	
61	// pathResolvedMsg reports the address the target resolved to.
62	type pathResolvedMsg struct {
63		gen      int
64		addr     netip.Addr
65		route    netcheck.RouteHop
66		routeErr error
67		source   pathSource                 // the source at launch
68		ctr      docker.ContainerNetworking // zero for this machine
69		ctrErr   error                      // logged by the producer, never shown
70	}
71	
72	// pathSourcesMsg carries what the selector offers once the engine answered.
73	type pathSourcesMsg struct {
74		gen  int // the request it answers, so a stale answer can be dropped
75		list pathSourceList
76	}
77	
78	// loadPathSourcesCmd reads the selector's list off the Update goroutine, under
79	// its own timeout so a hung engine cannot keep the selector loading. It
80	// touches no model (Rule 110): the answer comes back as a message.
81	func loadPathSourcesCmd(gen int, timeout time.Duration, e pathEngine) tea.Cmd {
82		return func() tea.Msg {
83			return pathSourcesMsg{gen: gen, list: listPathSourcesUnder(context.Background(), timeout, e)}
84		}
85	}
86	
87	// listPathSourcesUnder reads the list under a timeout derived from parent.
88	// Only parent decides whether an error is logged: a deadline exceeded on its
89	// own is a real failure, a canceled parent is not.
90	func listPathSourcesUnder(parent context.Context, timeout time.Duration, e pathEngine) pathSourceList {
91		ctx, cancel := context.WithTimeout(parent, timeout)
92		defer cancel()
93		return readPathSources(parent, ctx, e)
94	}
95	
96	// listPathSources reads what the selector offers with a single context.
97	func listPathSources(ctx context.Context, e pathEngine) pathSourceList {
98		return readPathSources(ctx, ctx, e)
99	}
100	
101	// readPathSources reads what the selector offers. Only read-only engine calls
102	// are made (info, ps): nothing starts or enters a container. A raw error goes
103	// to the log, never to the note, unless parent was canceled.
104	func readPathSources(parent, ctx context.Context, e pathEngine) pathSourceList {
105		name := ""
106		if e.engineName != nil {
107			name = e.engineName()
108		}
109		if name != "docker" { // podman: no exec at all
110			return sourceListFrom(name, "", nil, nil, nil)
111		}
112		osName, osErr := e.engineOS(ctx)
113		if osErr != nil {
114			logSourcesError(parent, osErr)
115			return sourceListFrom(name, "", osErr, nil, nil)
116		}
117		if isDockerDesktop(osName) {
118			return sourceListFrom(name, osName, nil, nil, nil)
119		}
120		cs, psErr := e.running(ctx)
121		if psErr != nil {
122			logSourcesError(parent, psErr)
123		}
124		return sourceListFrom(name, osName, nil, cs, psErr)
125	}
126	
127	// logSourcesError logs a read failure unless the caller gave up (parent is
128	// the context received, not the one bounded by the timeout).
129	func logSourcesError(parent context.Context, err error) {
130		if parent.Err() == nil {
131			log.Printf("ERROR [netdiag/path] sources: %v", err)
132		}
133	}
134	
135	// pathHopMsg carries one hop as the engine reports it.
136	type pathHopMsg struct {
137		gen int
138		hop nettrace.Hop
139	}
140	
141	// pathDoneMsg ends a run: a result, or an error when no trace happened.
142	type pathDoneMsg struct {
143		gen    int
144		result nettrace.Result
145		err    error
146	}
147	
148	// producePath resolves the target, traces it and sends the messages to out,
149	// then closes out. It runs inside a Cmd and touches no model (Rule 110).
150	// out must have room for pathChanCap messages: sends never block, so a view
151	// that stops reading after canceling leaks nothing.
152	func producePath(ctx context.Context, gen int, tg pathTarget, src pathSource, resolveTimeout time.Duration, e pathEngine, out chan tea.Msg) {
153		defer close(out)
154		send := func(m tea.Msg) {
155			select {
156			case out <- m:
157			default:
158			}
159		}
160		// sendDone must never be lost: when the channel is full the oldest message
161		// is dropped to make room. The producer is the only sender, so one drop
162		// frees a slot for good.
163		sendDone := func(m tea.Msg) {
164			for range 2 {
165				select {
166				case out <- m:
167					return
168				default:
169				}
170				select {
171				case <-out:
172				default:
173				}
174			}
175		}
176	
177		addr, err := resolvePathTarget(ctx, tg.Host, resolveTimeout, e)
178		if err != nil {
179			if ctx.Err() == nil { // esc during the resolution is not an error
180				log.Printf("ERROR [netdiag/path] resolve %s: %v", tg.Host, err)
181			}
182			sendDone(pathDoneMsg{gen: gen, err: err})
183			return
184		}
185		// The route is asked for the address actually traced. A failure is not
186		// fatal and is never shown: the trace goes on without the route column.
187		route, routeErr := e.route(ctx, addr)
188		if routeErr != nil && ctx.Err() == nil {
189			log.Printf("ERROR [netdiag/path] route %s: %v", tg.Host, routeErr)
190		}
191		ctr, ctrErr := inspectPathSource(ctx, src, resolveTimeout, e)
192		send(pathResolvedMsg{gen: gen, addr: addr, route: route, routeErr: routeErr, source: src, ctr: ctr, ctrErr: ctrErr})
193	
194		res, err := e.trace(ctx, addr, nettrace.Options{}, func(h nettrace.Hop) {
195			send(pathHopMsg{gen: gen, hop: h})
196		})
197		if err != nil {
198			log.Printf("ERROR [netdiag/path] trace %s: %v", tg.Host, err)
199		}
200		sendDone(pathDoneMsg{gen: gen, result: res, err: err})
201	}
202	
203	// inspectPathSource reads the chosen container's network under its own
204	// timeout. This machine reads nothing. A failure is not fatal and is never
205	// shown: the raw error goes to the log unless the run was canceled.
206	func inspectPathSource(ctx context.Context, src pathSource, timeout time.Duration, e pathEngine) (docker.ContainerNetworking, error) {
207		if src.isHost() {
208			return docker.ContainerNetworking{}, nil
209		}
210		ictx, cancel := context.WithTimeout(ctx, timeout)
211		defer cancel()
212		ctr, err := e.inspect(ictx, src.ID)
213		if err != nil && ctx.Err() == nil {
214			log.Printf("ERROR [netdiag/path] inspect %s: %v", src.ID, err)
215		}
216		return ctr, err
217	}
218	
219	// resolvePathTarget returns the IPv4 address to trace: a literal is used as
220	// is, a name is resolved under its own timeout.
221	func resolvePathTarget(ctx context.Context, host string, timeout time.Duration, e pathEngine) (netip.Addr, error) {
222		if a, err := netip.ParseAddr(host); err == nil && a.Is4() {
223			return a, nil
224		}
225		rctx, cancel := context.WithTimeout(ctx, timeout)
226		defer cancel()
227		addrs, err := e.resolve(rctx, host)
228		if err != nil {
229			return netip.Addr{}, fmt.Errorf("%w: %w", errPathResolve, err)
230		}
231		if len(addrs) == 0 {
232			return netip.Addr{}, errPathNoIPv4
233		}
234		return addrs[0], nil
235	}
236	
237	// waitForPathMsg returns a Cmd that yields the next message of in, or nil
238	// once in is closed. The view re-arms it after every message.
239	func waitForPathMsg(in <-chan tea.Msg) tea.Cmd {
240		return func() tea.Msg {
241			m, ok := <-in
242			if !ok {
243				return nil
244			}
245			return m
246		}
247	}
