609				for _, raw := range []string{"not found", "daemon down"} {
610					if strings.Contains(got.Note, raw) {
611						t.Fatalf("note %q leaks the raw error", got.Note)
612					}
613				}
614				if (tc.fake.osErr != nil || tc.fake.psErr != nil) && !strings.Contains(logs.String(), "ERROR [netdiag/path] sources:") {
615					t.Fatalf("raw error not logged: %q", logs.String())
616				}
617			})
618		}
619	}
