20	const producerWait = 2 * time.Second
21	
22	// fakeEngine records its calls; no socket, no resolver.
23	type fakeEngine struct {
24		resolveCalls int
25		resolveHost  string
26		resolveCtx   context.Context
27		traceCalls   int
28		traceAddr    netip.Addr
29		traceOpts    nettrace.Options
30		traceCtxErr  error
31		routeCalls   int
32		routeAddr    netip.Addr
33	
34		// Container source seam (DEVDESK-330): counters and recorded arguments.
35		engineNameVal string // "" means "docker"
36		osName        string // "" means a Linux engine
37		osErr         error
38		osCtx         context.Context
39		psRows        []docker.Container
40		psErr         error
41		osCalls       int
42		psCalls       int
43		inspectCalls  int
44		inspectIDs    []string
45		inspectNet    docker.ContainerNetworking
46		inspectErr    error
47		inspectCtx    context.Context
48	
49		routeFn   func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error)
50		resolveFn func(ctx context.Context, host string) ([]netip.Addr, error)
51		traceFn   func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error)
52	}
53	
54	func (f *fakeEngine) engine() pathEngine {
55		return pathEngine{
56			supported: func() error { return nil },
57			resolve: func(ctx context.Context, host string) ([]netip.Addr, error) {
58				f.resolveCalls++
59				f.resolveHost = host
60				f.resolveCtx = ctx
61				if f.resolveFn == nil {
62					return nil, errors.New("unexpected resolve")
63				}
64				return f.resolveFn(ctx, host)
65			},
66			route: func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error) {
67				f.routeCalls++
68				f.routeAddr = a
69				if f.routeFn == nil {
70					return defaultRouteHop(), nil
71				}
72				return f.routeFn(ctx, a)
73			},
74			trace: func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
75				f.traceCalls++
76				f.traceAddr = a
77				f.traceOpts = o
78				f.traceCtxErr = ctx.Err()
79				if f.traceFn == nil {
80					return nettrace.Result{Target: a}, nil
81				}
82				return f.traceFn(ctx, a, o, onHop)
83			},
84			engineName: func() string {
85				if f.engineNameVal == "" {
86					return "docker"
87				}
88				return f.engineNameVal
89			},
90			engineOS: func(ctx context.Context) (string, error) {
91				f.osCalls++
92				f.osCtx = ctx
93				if f.osName == "" && f.osErr == nil {
94					return "Debian GNU/Linux 13 (trixie)", nil
95				}
96				return f.osName, f.osErr
97			},
98			running: func(context.Context) ([]docker.Container, error) {
99				f.psCalls++
100				return f.psRows, f.psErr
101			},
102			inspect: func(ctx context.Context, id string) (docker.ContainerNetworking, error) {
103				f.inspectCalls++
104				f.inspectIDs = append(f.inspectIDs, id)
105				f.inspectCtx = ctx
106				return f.inspectNet, f.inspectErr
107			},
108		}
109	}
110	
111	func hopAt(ttl int) nettrace.Hop {
112		return nettrace.Hop{TTL: ttl, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr("10.0.0.1")}
113	}
114	
115	// runProducer calls producePath synchronously with nobody reading the
116	// channel, failing if it does not return (the channel capacity must hold).
117	func runProducer(t *testing.T, ctx context.Context, gen int, tg pathTarget, rt time.Duration, e pathEngine) []tea.Msg {
118		t.Helper()
119		return runProducerFrom(t, ctx, gen, tg, hostSource(), rt, e)
120	}
121	
122	// runProducerFrom is runProducer for a given source.
123	func runProducerFrom(t *testing.T, ctx context.Context, gen int, tg pathTarget, src pathSource, rt time.Duration, e pathEngine) []tea.Msg {
124		t.Helper()
125		out := make(chan tea.Msg, pathChanCap)
126		done := make(chan struct{})
127		go func() {
128			defer close(done)
129			producePath(ctx, gen, tg, src, rt, e, out)
130		}()
131		select {
132		case <-done:
133		case <-time.After(producerWait):
134			t.Fatal("producePath did not return: the producer blocked")
135		}
136		var msgs []tea.Msg
137		for {
138			select {
139			case m, ok := <-out:
140				if !ok {
141					return msgs
142				}
143				msgs = append(msgs, m)
144			default:
145				t.Fatal("channel not closed after producePath returned")
146				return nil
147			}
148		}
149	}
150	
151	func TestPathChanCapHoldsAWholeTrace(t *testing.T) {
152		if want := nettrace.MaxHopsLimit + 2; pathChanCap != want {
153			t.Fatalf("pathChanCap = %d, want %d", pathChanCap, want)
154		}
155		if pathChanCap != 32 {
156			t.Fatalf("pathChanCap = %d, want 32", pathChanCap)
157		}
158	}
159	
160	func TestProducePathLiteralIPv4SkipsResolve(t *testing.T) {
161		f := &fakeEngine{traceFn: func(_ context.Context, a netip.Addr, _ nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
162			onHop(hopAt(1))
163			onHop(hopAt(2))
164			return nettrace.Result{Target: a, Outcome: nettrace.OutcomeReached, Hops: []nettrace.Hop{hopAt(1), hopAt(2)}}, nil
165		}}
166		msgs := runProducer(t, context.Background(), 7, pathTarget{Host: "1.1.1.1"}, time.Second, f.engine())
167	
168		if f.resolveCalls != 0 {
169			t.Fatalf("resolve called %d times for a literal IPv4", f.resolveCalls)
170		}
171		if f.traceOpts != (nettrace.Options{}) {
172			t.Fatalf("trace options = %+v, want the zero Options", f.traceOpts)
173		}
174		if len(msgs) != 4 {
175			t.Fatalf("got %d messages, want 4 (resolved, 2 hops, done): %#v", len(msgs), msgs)
176		}
