9	// hostBridge returns the name of this machine's interface called exactly want
10	// (case sensitive) that carries gw among its IPv4 addresses, or "" when there
11	// is none. Malformed CIDR entries are ignored.
12	func hostBridge(want string, gw netip.Addr, ifaces []netiface.Interface) string {
13		if want == "" || !gw.IsValid() {
14			return ""
15		}
16		for _, ifc := range ifaces {
17			if ifc.Name != want {
18				continue
19			}
20			for _, cidr := range ifc.IPv4 {
21				if p, err := netip.ParsePrefix(cidr); err == nil && p.Addr() == gw {
22					return ifc.Name
23				}
24			}
25		}
26		return ""
27	}
