1	package netdiag
2	
3	import (
4		"fmt"
5		"go/ast"
6		"go/parser"
7		"go/token"
8		"os"
9		"path/filepath"
10		"slices"
11		"strconv"
12		"strings"
13		"testing"
14	)
15	
16	// DEVDESK-330 criterion 7, view level: the Path tab reaches the container
17	// engine only through a fixed list of read functions, and no source file of the
18	// package names a verb that starts, creates or enters a container. The runtime
19	// half is TestPathEngineReadsStartNothing.
20	//
21	// What the guard sees: selectors on the docker and engine packages (aliases
22	// included, dot imports refused), string literals and constant concatenations
23	// and fmt.Sprint* calls over literals whose words include a forbidden verb
24	// (case-insensitive, per word: "container START abc" is caught, UI prose such
25	// as "Run again" is not), imports of
26	// os/exec, execabs, syscall, calls to os.StartProcess, and any internal
27	// package that is not on allowedInternalImports.
28	//
29	// What it does not see, by construction: a verb assembled from variables or
30	// read at run time (a config value, an environment variable, strings.Join over
31	// a slice, a rune loop), and a read function of the docker package that itself
32	// starts something (the allowed list is the contract; those functions are
33	// covered by internal/docker's own tests and by the runtime half).
34	
35	const (
36		dockerImportPath   = "github.com/anthnel/devdesk/internal/docker"
37		engineImportPath   = "github.com/anthnel/devdesk/internal/engine"
38		internalImportBase = "github.com/anthnel/devdesk/internal/"
39	)
40	
41	// allowedDockerUses is every docker.<X> the Path tab may name: the read
42	// functions and the types they return.
43	var allowedDockerUses = []string{
44		"Container", "ContainerNetworking", "EndpointNetwork",
45		"ListContainersContext", "EngineOperatingSystem", "InspectContainerNetworking",
46		"IsContainerID",
47	}
48	
49	// allowedEngineUses is every engine.<X> the Path tab may name.
50	var allowedEngineUses = []string{"Current"}
51	
52	// allowedInternalImports is every internal package the netdiag sources import.
53	// A new one fails the guard so that it is looked at once: a package that can
54	// reach the engine or a process must not slip in through a helper.
55	var allowedInternalImports = []string{
56		"command", "config", "docker", "engine", "forward", "jobs", "netcheck",
57		"netiface", "nettrace", "ports", "shared",
58		"ui/components", "ui/datatable", "ui/help", "ui/indicator", "ui/keymap",
59		"ui/overlay", "ui/shortcut", "ui/theme",
60	}
61	
62	// forbiddenImports start processes: the Path tab has no business with them.
63	var forbiddenImports = []string{"os/exec", "golang.org/x/sys/execabs", "syscall"}
64	
65	// forbiddenVerbs are engine arguments that change a container or open a shell
66	// in it. A string whose words include one of them has no business in this
67	// package.
68	var forbiddenVerbs = []string{
69		"start", "exec", "run", "cp", "attach", "create", "restart", "unpause",
70		"kill", "stop", "pause", "rm", "commit",
71	}
72	
73	// engineWords are the words after which a verb is an engine command line
74	// ("container start abc", "docker exec -it"), as opposed to prose.
75	var engineWords = []string{"docker", "podman", "container", "engine"}
76	
77	// verbIn returns the forbidden verb s names, ignoring case and surrounding
78	// punctuation: either s is that one word, or a word of s is one right after an
79	// engine word. UI prose ("Run again", "Pause forward", "Kill process") is not an
80	// engine command and is deliberately not flagged; a verb at the head of a
81	// multi-word string with no engine word before it is the guard's blind spot.
82	func verbIn(s string) (string, bool) {
83		words := strings.Fields(s)
84		for i, w := range words {
85			words[i] = strings.ToLower(strings.Trim(w, `.,:;!?()[]{}"'`+"`"))
86		}
87		if len(words) == 1 && slices.Contains(forbiddenVerbs, words[0]) {
88			return words[0], true
89		}
90		for i := 1; i < len(words); i++ {
91			if slices.Contains(forbiddenVerbs, words[i]) && slices.Contains(engineWords, words[i-1]) {
92				return words[i], true
93			}
94		}
95		return "", false
96	}
97	
98	// constString folds a string literal, or a + of foldable operands, to its value.
99	func constString(e ast.Expr) (string, bool) {
100		switch x := e.(type) {
101		case *ast.BasicLit:
102			if x.Kind != token.STRING {
103				return "", false
104			}
105			s, err := strconv.Unquote(x.Value)
106			return s, err == nil
107		case *ast.ParenExpr:
108			return constString(x.X)
109		case *ast.BinaryExpr:
110			if x.Op != token.ADD {
111				return "", false
112			}
113			l, lok := constString(x.X)
114			r, rok := constString(x.Y)
115			return l + r, lok && rok
116		}
117		return "", false
118	}
119	
120	// sprintResult evaluates fmt.Sprint* when every argument is a literal, so a
121	// verb assembled by "%s%s", "sta", "rt" is seen. ok is false otherwise.
122	func sprintResult(name string, args []ast.Expr) (string, bool) {
123		vals := make([]any, 0, len(args))
124		for _, a := range args {
125			if s, ok := constString(a); ok {
126				vals = append(vals, s)
127				continue
128			}
129			if lit, ok := a.(*ast.BasicLit); ok && lit.Kind == token.INT {
130				n, err := strconv.Atoi(lit.Value)
131				if err != nil {
132					return "", false
133				}
134				vals = append(vals, n)
135				continue
136			}
137			return "", false
138		}
139		switch name {
140		case "Sprintf":
141			format, ok := vals[0].(string)
142			if !ok {
143				return "", false
144			}
145			return fmt.Sprintf(format, vals[1:]...), true
146		case "Sprint":
147			return fmt.Sprint(vals...), true
148		case "Sprintln":
149			return fmt.Sprintln(vals...), true
150		}
151		return "", false
152	}
153	
154	// engineViolations parses one Go source and returns one line per forbidden use
155	// (see the head comment for what that covers).
156	func engineViolations(filename string, src any) ([]string, error) {
157		fset := token.NewFileSet()
158		f, err := parser.ParseFile(fset, filename, src, 0)
159		if err != nil {
160			return nil, err
161		}
162		allowed := map[string][]string{} // local package name -> allowed selectors
163		var osName, fmtName string
164		var out []string
165		report := func(pos token.Pos, what string) {
166			out = append(out, filepath.Base(filename)+":"+strconv.Itoa(fset.Position(pos).Line)+": "+what)
167		}
168		for _, imp := range f.Imports {
169			path, _ := strconv.Unquote(imp.Path.Value)
170			local := filepath.Base(path)
171			if imp.Name != nil {
172				local = imp.Name.Name
173			}
174			if local == "." {
175				report(imp.Pos(), "dot import of "+path+" hides what is used")
176			}
177			switch path {
178			case dockerImportPath:
179				allowed[local] = allowedDockerUses
180			case engineImportPath:
181				allowed[local] = allowedEngineUses
182			case "os":
183				osName = local
184			case "fmt":
185				fmtName = local
186			}
187			if slices.Contains(forbiddenImports, path) {
188				report(imp.Pos(), "imports "+path)
189			}
190			if rest, ok := strings.CutPrefix(path, internalImportBase); ok && !slices.Contains(allowedInternalImports, rest) {
191				report(imp.Pos(), "imports internal/"+rest+", which is not on the netdiag import list")
192			}
193		}
194		ast.Inspect(f, func(n ast.Node) bool {
195			switch x := n.(type) {
196			case *ast.SelectorExpr:
197				checkSelector(x, allowed, osName, report)
198			case *ast.BinaryExpr:
199				if s, ok := constString(x); ok {
200					checkVerb(x.Pos(), s, "constant string", report)
201					return false // the folded value covers every operand
202				}
203			case *ast.BasicLit:
204				if s, ok := constString(x); ok {
205					checkVerb(x.Pos(), s, "string literal "+x.Value, report)
206				}
207			case *ast.CallExpr:
208				checkSprint(x, fmtName, report)
209			}
210			return true
211		})
212		return out, nil
213	}
214	
215	func checkSelector(x *ast.SelectorExpr, allowed map[string][]string, osName string, report func(token.Pos, string)) {
216		id, ok := x.X.(*ast.Ident)
217		if !ok {
218			return
219		}
220		if list, isPkg := allowed[id.Name]; isPkg && !slices.Contains(list, x.Sel.Name) {
221			report(x.Pos(), id.Name+"."+x.Sel.Name+" is not on the read-only list")
222		}
223		if osName != "" && id.Name == osName && x.Sel.Name == "StartProcess" {
224			report(x.Pos(), "os.StartProcess starts a process")
225		}
226	}
227	
228	func checkVerb(pos token.Pos, s, what string, report func(token.Pos, string)) {
229		if v, bad := verbIn(s); bad {
230			report(pos, what+" "+strconv.Quote(s)+" holds the engine verb "+strconv.Quote(v)+" that changes a container")
231		}
232	}
233	
234	// checkSprint reports a fmt.Sprint* over literals whose result holds a verb the
235	// format string alone does not (those are already reported as literals).
236	func checkSprint(call *ast.CallExpr, fmtName string, report func(token.Pos, string)) {
237		sel, ok := call.Fun.(*ast.SelectorExpr)
238		if !ok || fmtName == "" || len(call.Args) == 0 {
239			return
240		}
241		if id, isIdent := sel.X.(*ast.Ident); !isIdent || id.Name != fmtName {
242			return
243		}
244		res, ok := sprintResult(sel.Sel.Name, call.Args)
245		if !ok {
246			return
247		}
248		if first, isConst := constString(call.Args[0]); isConst {
249			if _, already := verbIn(first); already {
250				return
251			}
252		}
253		checkVerb(call.Pos(), res, "fmt."+sel.Sel.Name+" result", report)
254	}
255	
256	func TestPathTabCallsOnlyReadOnlyEngineFunctions(t *testing.T) {
257		files, err := filepath.Glob("*.go")
258		if err != nil || len(files) == 0 {
259			t.Fatalf("no source file found (err %v)", err)
260		}
261		scanned := 0
262		for _, file := range files {
263			if strings.HasSuffix(file, "_test.go") {
264				continue
265			}
266			raw, err := os.ReadFile(file)
267			if err != nil {
268				t.Fatal(err)
269			}
270			got, err := engineViolations(file, raw)
271			if err != nil {
272				t.Fatalf("%s: %v", file, err)
273			}
274			for _, v := range got {
275				t.Errorf("%s", v)
276			}
277			scanned++
278		}
279		if scanned < 10 {
280			t.Fatalf("scanned %d files: the guard would pass on nothing", scanned)
281		}
282	}
283	
284	// The detector itself: it fails on each kind of forbidden use, an alias or a
285	// concatenation does not hide one, and clean code passes.
286	func TestEngineViolationsDetectsForbiddenUses(t *testing.T) {
287		const head = "package netdiag\nimport (\n\t\"fmt\"\n\t\"os\"\n\t\"github.com/anthnel/devdesk/internal/docker\"\n\teng \"github.com/anthnel/devdesk/internal/engine\"\n)\nvar _ = fmt.Sprint\nvar _ = os.Getenv\n"
288		cases := []struct {
289			name string
290			body string
291			want int
292		}{
293			{"clean", "var _ = docker.ListContainersContext\nvar _ docker.Container\nvar _ = docker.IsContainerID\nvar _ = eng.Current", 0},
294			{"docker function outside the list", "var _ = docker.StartContainer", 1},
295			{"docker exec", "var _ = docker.ExecInContainer", 1},
296			{"engine function outside the list", "var _ = eng.Run", 1},
297			{"verb as an argument", "var _ = []string{\"container\", \"start\", \"abc\"}", 1},
298			{"exec verb", "var _ = []string{\"exec\", \"-it\"}", 1},
299			{"run verb", "var _ = \"run\"", 1},
300			{"cp verb", "var _ = \"cp\"", 1},
301			{"attach verb", "var _ = \"attach\"", 1},
302			{"constant", "const verb = \"start\"", 1},
303			{"concatenation", "var _ = \"sta\" + \"rt\"", 1},
304			{"concatenation in parentheses", "var _ = (\"ki\" + \"l\") + \"l\"", 1},
305			{"upper case", "var _ = \"START\"", 1},
306			{"mixed case", "var _ = \"Restart\"", 1},
307			{"multi-word string", "var _ = \"container start abc\"", 1},
308			{"multi-word with punctuation", "var _ = \"docker exec, then stop\"", 1},
309			{"sprintf assembling a verb", "var _ = fmt.Sprintf(\"%s%s\", \"sta\", \"rt\")", 1},
310			{"sprintf assembling an engine command", "var _ = fmt.Sprintf(\"container %s%s\", \"sta\", \"rt\")", 1},
311			{"sprintf with a verb argument", "var _ = fmt.Sprintf(\"container %s\", \"x\") + \"stop\"", 1},
312			{"os.StartProcess", "var _ = os.StartProcess", 1},
313			{"read verbs are fine", "var _ = []string{\"ps\", \"info\", \"container\", \"inspect\"}", 0},
314			{"prose with a verb is not a command", "var _ = []string{\"Run again\", \"Pause forward\", \"Kill process\", \"Stop forwarding %s to %s?\"}", 0},
315			{"words that only contain a verb", "var _ = \"The column starts on this machine; a running container, restarts nothing here\"", 0},
316			{"clean sprintf", "var _ = fmt.Sprintf(\"%s hops to %s\", \"3\", \"host\")", 0},
317			{"sprintf over variables", "func f(a, b string) string { return fmt.Sprintf(\"%s%s\", a, b) }", 0},
318			{"os.Getenv", "var _ = os.Getenv(\"HOME\")", 0},
319			{"non-string constant arithmetic", "var _ = 1 + 2", 0},
320		}
321		for _, tc := range cases {
322			t.Run(tc.name, func(t *testing.T) {
323				got, err := engineViolations("synthetic.go", head+tc.body+"\n")
324				if err != nil {
325					t.Fatal(err)
326				}
327				if len(got) != tc.want {
328					t.Errorf("violations = %v, want %d", got, tc.want)
329				}
330			})
331		}
332		importCases := []struct {
333			name string
334			src  string
335			want int
336		}{
337			{"os/exec", "package netdiag\nimport \"os/exec\"\nvar _ = exec.Command\n", 1},
338			{"execabs", "package netdiag\nimport \"golang.org/x/sys/execabs\"\nvar _ = execabs.Command\n", 1},
339			{"syscall", "package netdiag\nimport \"syscall\"\nvar _ = syscall.Getpid\n", 1},
340			{"aliased docker import", "package netdiag\nimport d \"github.com/anthnel/devdesk/internal/docker\"\nvar _ = d.StartContainer\n", 1},
341			{"aliased docker import, allowed use", "package netdiag\nimport d \"github.com/anthnel/devdesk/internal/docker\"\nvar _ = d.IsContainerID\n", 0},
342			{"dot import of docker", "package netdiag\nimport . \"github.com/anthnel/devdesk/internal/docker\"\nvar _ = StartContainer\n", 1},
343			{"dot import of engine", "package netdiag\nimport . \"github.com/anthnel/devdesk/internal/engine\"\nvar _ = Run\n", 1},
344			{"internal package off the list", "package netdiag\nimport \"github.com/anthnel/devdesk/internal/oci\"\nvar _ = oci.X\n", 1},
345			{"internal package on the list", "package netdiag\nimport \"github.com/anthnel/devdesk/internal/ui/theme\"\nvar _ = theme.X\n", 0},
346			{"third-party package", "package netdiag\nimport \"github.com/charmbracelet/x/ansi\"\nvar _ = ansi.Strip\n", 0},
347		}
348		for _, tc := range importCases {
349			t.Run(tc.name, func(t *testing.T) {
350				got, err := engineViolations("synthetic.go", tc.src)
351				if err != nil {
352					t.Fatal(err)
353				}
354				if len(got) != tc.want {
355					t.Errorf("violations = %v, want %d", got, tc.want)
356				}
357			})
358		}
359	}
