92	// defaultRouteNetwork picks the network that holds the container's default
93	// route: among the endpoints with a gateway, the one with the strictly highest
94	// gateway priority. A tie, or a priority missing among several candidates, is
95	// never guessed. The input is not modified.
96	func defaultRouteNetwork(nets []docker.EndpointNetwork) (docker.EndpointNetwork, bool) {
97		var candidates []docker.EndpointNetwork
98		for _, e := range nets {
99			if e.Gateway.IsValid() {
100				candidates = append(candidates, e)
101			}
102		}
103		switch len(candidates) {
104		case 0:
105			return docker.EndpointNetwork{}, false
106		case 1:
107			return candidates[0], true
108		}
109		best := -1
110		for i, e := range candidates {
111			if e.GwPriority == nil {
112				return docker.EndpointNetwork{}, false
113			}
114			if best < 0 || *e.GwPriority > *candidates[best].GwPriority {
115				best = i
116			}
117		}
118		for i, e := range candidates {
119			if i != best && *e.GwPriority == *candidates[best].GwPriority {
120				return docker.EndpointNetwork{}, false
121			}
122		}
123		return candidates[best], true
124	}
