127	func (c pathContainer) containerText() string {
128		switch {
129		case c.Known && !c.Running:
130			return c.Name + " (" + textNotRunning + ")"
131		case c.Attach == attachNetwork && c.Addr.IsValid():
132			return c.Name + " (" + c.Addr.String() + ")"
133		}
134		return c.Name
135	}
136	
137	// networkText is the Address cell of the network row.
138	func (c pathContainer) networkText() string {
139		switch c.Attach {
140		case attachNetwork:
141			if c.Gateway.IsValid() {
142				return c.Network + " via " + c.Gateway.String()
143			}
144			return c.Network
145		case attachHost:
146			return textHostNetwork
147		case attachNone:
148			return textNoNetwork
149		case attachShared:
150			return textSharedNetwork
151		}
152		if c.Networks > 1 {
153			return fmt.Sprintf("%s (%d networks)", textUndetermined, c.Networks)
154		}
155		return textUndetermined
156	}
157	
158	// traceText is the Address cell of the trace row.
159	func (c pathContainer) traceText() string {
160		if c.Attach == attachHost {
161			return textTraceSharedHost
162		}
163		return textTraceFromHost
164	}
165	
166	// dimNetwork reports whether the network row says nothing about a path.
167	func (c pathContainer) dimNetwork() bool {
168		return c.Attach == attachUndetermined || c.Attach == attachNone
169	}
