	if got != "docker0" {
		t.Fatalf("bridge = %q, want docker0", got)
	}
	if !slices.Equal(f.networkIDs, []string{testNetID}) {
		t.Fatalf("network ids = %v, want [%s]", f.networkIDs, testNetID)
	}
