		{Name: "a_net", NetworkID: "id-a", Gateway: netip.MustParseAddr("172.18.0.1"), GwPriority: prioOf(0)},
		{Name: "b_net", NetworkID: "id-b", Gateway: netip.MustParseAddr("172.19.0.1"), GwPriority: prioOf(10)},
